-- 达梦：查看旧版本建库属性（目标版本不支持时会报字段／函数不存在）
SELECT SF_GET_LENGTH_IN_CHAR();
SELECT * FROM V$PARAMETER WHERE NAME = 'LENGTH_IN_CHAR';

-- 达梦：新建字段显式指定字符语义（按实际表名、列名和长度修改）
ALTER TABLE <SCHEMA>.<TABLE_NAME> ADD <COLUMN_NAME> VARCHAR(100 CHAR);

-- 达梦：先核对当前实例是否提供该参数
SELECT * FROM V$DM_INI WHERE PARA_NAME='NLS_LENGTH_SEMANTICS';
-- 实例提供且允许修改时，确认后设置系统默认及文件值
SP_SET_INI_PARA_VALUE(1,'NLS_LENGTH_SEMANTICS','CHAR');
-- DDL 也可显式指定字符单位
-- VARCHAR(100 CHAR)
